import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.DZhUhjDB.js";const u=JSON.parse('{"title":"02 — SEGURIDAD DE LA INFORMACIÓN","description":"02 — SEGURIDAD DE LA INFORMACIÓN","frontmatter":{"title":"02 — SEGURIDAD DE LA INFORMACIÓN","description":"02 — SEGURIDAD DE LA INFORMACIÓN"},"headers":[],"relativePath":"modules/seguridad-informacion/index.md","filePath":"modules/seguridad-informacion/index.md","lastUpdated":1787319749000}'),d={name:"modules/seguridad-informacion/index.md"};function i(s,t,n,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[r(`<div align="center"><blockquote><p>🚀 <strong>¿Eres principiante?</strong> Antes de este módulo, revisa la <strong><a href="./../00-FUNDAMENTOS/">base común del repo</a></strong> (1 carpeta atrás). Conceptos de GRC, auditoría y cumplimiento se entienden mejor con la base asentada.</p><p>Elige tu ruta de aprendizaje: 🛡️ <a href="./../00-FUNDAMENTOS/rutas/ruta-defensor">Defensor</a> · ⚔️ <a href="./../00-FUNDAMENTOS/rutas/ruta-atacante">Atacante</a> · 🤖 <a href="./../00-FUNDAMENTOS/rutas/ruta-ai-security">AI Security</a></p></blockquote><h1 id="🔵-02-—-seguridad-de-la-informacion" tabindex="-1">🔵 02 — SEGURIDAD DE LA INFORMACIÓN</h1><p><strong>Defensiva · SOC · Blue Team · DevSecOps · GRC</strong></p><p><em>&quot;La detección sin respuesta es solo telemetría cara.&quot;</em></p></div><hr><h2 id="🎯-proposito" tabindex="-1">🎯 Propósito</h2><p>Esta sección agrupa todo el conocimiento defensivo, de operaciones de seguridad (SOC), DevSecOps, hardening, cumplimiento normativo y threat intelligence. Cada subdominio se mapea explícitamente a los marcos <strong>NIST CSF 2.0</strong>, <strong>ISO 27001:2022</strong> y <strong>MITRE D3FEND</strong>.</p><hr><h2 id="🗺️-mapa-de-subdominios" tabindex="-1">🗺️ Mapa de subdominios</h2><table tabindex="0"><thead><tr><th>#</th><th>Subdominio</th><th>NIST CSF Function</th><th>ISO 27001 Anexo A</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-gestion-riesgos/">Gestión de Riesgos</a></td><td>Govern · Identify</td><td>A.5</td></tr><tr><td>02</td><td><a href="./02-blue-team-defensa/">Blue Team / Defensa</a></td><td>Detect · Respond</td><td>A.8.16</td></tr><tr><td>03</td><td><a href="./03-soc-operations/">SOC Operations</a></td><td>Detect · Respond</td><td>A.5.24-29</td></tr><tr><td>04</td><td><a href="./04-devsecops/">DevSecOps</a></td><td>Protect</td><td>A.8.25-34</td></tr><tr><td>05</td><td><a href="./05-hardening/">Hardening</a></td><td>Protect</td><td>A.8.9-19</td></tr><tr><td>06</td><td><a href="./06-compliance-normativas/">Compliance / Normativas</a></td><td>Govern</td><td>A.5.31-36</td></tr><tr><td>07</td><td><a href="./07-threat-intelligence/">Threat Intelligence</a></td><td>Identify · Detect</td><td>A.5.7</td></tr></tbody></table><hr><h2 id="📋-01-—-gestion-de-riesgos" tabindex="-1">📋 01 — Gestión de Riesgos</h2><blockquote><p><strong>Objetivo:</strong> identificar, evaluar y tratar riesgos de seguridad de manera sistemática.</p></blockquote><p><strong>Frameworks:</strong></p><ul><li><strong>ISO/IEC 27001:2022</strong> — SGSI (Sistema de Gestión de Seguridad de la Información)</li><li><strong>ISO/IEC 27005:2022</strong> — gestión de riesgos específica</li><li><strong>NIST RMF (SP 800-37)</strong> — Risk Management Framework</li><li><strong>NIST SP 800-30</strong> — guía de evaluación de riesgos</li><li><strong>OCTAVE Allegro</strong> — alternativa cualitativa</li></ul><p><strong>Entregables esperados:</strong></p><ul><li>Matrices de riesgo (probabilidad × impacto)</li><li>Plantillas de declaración de aplicabilidad (SoA)</li><li>Plan de tratamiento de riesgos (RTP)</li></ul><p>📁 <a href="./01-gestion-riesgos/"><code>./01-gestion-riesgos/</code></a></p><hr><h2 id="🛡️-02-—-blue-team-defensa" tabindex="-1">🛡️ 02 — Blue Team / Defensa</h2><blockquote><p><strong>Objetivo:</strong> detectar, contener y erradicar amenazas en tiempo real.</p></blockquote><p><strong>Stack defensivo:</strong></p><ul><li>🔵 <strong>Wazuh</strong> — SIEM + XDR open source <em>(stack principal)</em></li><li>🦁 <strong>Suricata</strong> — IDS/IPS de red</li><li>🦌 <strong>Sigma</strong> — formato vendor-agnostic de reglas de detección</li><li>🐍 <strong>YARA</strong> — pattern matching para malware</li><li>📡 <strong>Sysmon</strong> — telemetría avanzada en Windows</li></ul><p><strong>Subcarpetas:</strong></p><ul><li><code>siem-wazuh/</code> — instalación, decoders, reglas custom, integraciones</li><li><code>threat-hunting/</code> — hipótesis estructuradas (PEAK, TaHiTI, MaGMA)</li><li><code>herramientas/</code> — Wazuh · Suricata · YARA · Velociraptor</li><li><code>mitre-d3fend/</code> — contramedidas defensivas mapeadas a ATT&amp;CK</li></ul><p><strong>Detection Engineering:</strong></p><ul><li>Detection-as-Code en Git (reglas versionadas)</li><li>CI/CD para validar reglas con datasets sintéticos (Atomic Red Team, Mordor)</li></ul><p>📁 <a href="./02-blue-team-defensa/"><code>./02-blue-team-defensa/</code></a></p><hr><h2 id="🚨-03-—-soc-operations" tabindex="-1">🚨 03 — SOC Operations</h2><blockquote><p><strong>Objetivo:</strong> operar un Security Operations Center con procesos repetibles.</p></blockquote><p><strong>Estructura típica de un SOC:</strong></p><ul><li><strong>Tier 1</strong> — triage de alertas, escalado</li><li><strong>Tier 2</strong> — investigación profunda, contención</li><li><strong>Tier 3</strong> — threat hunting, forense, malware analysis</li><li><strong>SOC Manager</strong> — métricas, mejora continua</li></ul><p><strong>Carpetas:</strong></p><table tabindex="0"><thead><tr><th>Carpeta</th><th>Contenido</th></tr></thead><tbody><tr><td><code>playbooks/</code></td><td>Procedimientos paso a paso (basados en NIST 800-61)</td></tr><tr><td><code>incident-response/</code></td><td>Casos reales documentados (anonimizados)</td></tr><tr><td><code>alertas-y-dashboards/</code></td><td>Queries Wazuh / KQL / SPL · paneles Kibana</td></tr></tbody></table><p><strong>Métricas SOC clave:</strong></p><ul><li>MTTD (Mean Time To Detect)</li><li>MTTR (Mean Time To Respond)</li><li>Tasa de falsos positivos</li><li>Cobertura MITRE ATT&amp;CK (porcentaje de técnicas detectadas)</li></ul><p>📁 <a href="./03-soc-operations/"><code>./03-soc-operations/</code></a></p><hr><h2 id="⚙️-04-—-devsecops" tabindex="-1">⚙️ 04 — DevSecOps</h2><blockquote><p><strong>Objetivo:</strong> integrar seguridad en cada fase del SDLC sin frenar la entrega.</p></blockquote><p><strong>Subcarpetas:</strong></p><table tabindex="0"><thead><tr><th>Subcarpeta</th><th>Stack</th></tr></thead><tbody><tr><td><code>ci-cd-security/</code></td><td>GitHub Actions · GitLab CI · pipeline gates</td></tr><tr><td><code>secret-scanning/</code></td><td><strong>TruffleHog</strong> · <strong>GitLeaks</strong> · <code>detect-secrets</code> · <code>gitleaks-pre-commit</code></td></tr><tr><td><code>docker-security/</code></td><td>Trivy · Grype · Dockle · Hadolint · Cosign · distroless</td></tr><tr><td><code>sast-dast/</code></td><td>Semgrep · Bandit · CodeQL (SAST) · OWASP ZAP · Nuclei (DAST)</td></tr></tbody></table><p><strong>Principios aplicados:</strong></p><ul><li><strong>Shift-left</strong> — seguridad desde el commit, no desde producción</li><li><strong>Policy-as-Code</strong> — OPA / Kyverno para Kubernetes</li><li><strong>Supply chain security</strong> — SBOM (CycloneDX) · firma con Cosign · SLSA</li><li><strong>Least privilege</strong> — non-root containers · read-only FS · capabilities mínimas</li></ul><p><strong>Pipeline de referencia:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commit → secret-scan → SAST → build → SBOM → image-scan → sign → DAST → deploy</span></span></code></pre></div><p>📁 <a href="./04-devsecops/"><code>./04-devsecops/</code></a></p><hr><h2 id="🔒-05-—-hardening" tabindex="-1">🔒 05 — Hardening</h2><blockquote><p><strong>Objetivo:</strong> reducir superficie de ataque en sistemas operativos y red.</p></blockquote><p><strong>Subcarpetas:</strong></p><table tabindex="0"><thead><tr><th>Subcarpeta</th><th>Estándares de referencia</th></tr></thead><tbody><tr><td><code>linux/</code></td><td>CIS Benchmarks · STIG · <code>Lynis</code> · <code>OpenSCAP</code></td></tr><tr><td><code>windows/</code></td><td>CIS Benchmarks · LAPS · BitLocker · AppLocker · Credential Guard</td></tr><tr><td><code>redes/</code></td><td>Segmentación · firewalls · 802.1X · DNS-sec · port security</td></tr></tbody></table><p><strong>Herramientas de auditoría:</strong></p><ul><li><code>Lynis</code> (Linux) · <code>Microsoft Security Compliance Toolkit</code> · <code>CIS-CAT</code></li></ul><p>📁 <a href="./05-hardening/"><code>./05-hardening/</code></a></p><hr><h2 id="📜-06-—-compliance-y-normativas" tabindex="-1">📜 06 — Compliance y Normativas</h2><blockquote><p><strong>Objetivo:</strong> mapear controles técnicos a requisitos legales y regulatorios.</p></blockquote><p><strong>Subcarpetas:</strong></p><table tabindex="0"><thead><tr><th>Subcarpeta</th><th>Marco</th></tr></thead><tbody><tr><td><code>gdpr/</code></td><td>Reglamento (UE) 2016/679 — Protección de datos UE</td></tr><tr><td><code>iso-27001/</code></td><td>ISO/IEC 27001:2022 + Anexo A (93 controles)</td></tr><tr><td><code>colombia-ley-1581/</code></td><td>Ley 1581 de 2012 + Decreto 1377/2013 — Habeas Data 🇨🇴</td></tr></tbody></table><p><strong>Otros marcos referenciados:</strong></p><ul><li><strong>NIST CSF 2.0</strong> · <strong>CIS Controls v8</strong> · <strong>PCI-DSS v4.0</strong> · <strong>HIPAA</strong> · <strong>SOC 2</strong></li></ul><p>📁 <a href="./06-compliance-normativas/"><code>./06-compliance-normativas/</code></a></p><hr><h2 id="🕵️-07-—-threat-intelligence" tabindex="-1">🕵️ 07 — Threat Intelligence</h2><blockquote><p><strong>Objetivo:</strong> anticipar ataques con inteligencia operativa, táctica y estratégica.</p></blockquote><p><strong>Subcarpetas:</strong></p><table tabindex="0"><thead><tr><th>Subcarpeta</th><th>Contenido</th></tr></thead><tbody><tr><td><code>mitre-attack/</code></td><td>Matrices: Enterprise · Mobile · ICS · navigator layers propios</td></tr><tr><td><code>feeds/</code></td><td>Listas de IPs/dominios maliciosos · OSINT feeds (AbuseIPDB, AlienVault OTX)</td></tr><tr><td><code>iocs/</code></td><td>IOCs versionados (STIX/TAXII · MISP)</td></tr></tbody></table><p><strong>Niveles de TI:</strong></p><ul><li><strong>Estratégica</strong> — ¿quién y por qué? (informes APT)</li><li><strong>Operativa</strong> — ¿cómo atacan? (TTPs)</li><li><strong>Táctica</strong> — ¿qué herramientas usan?</li><li><strong>Técnica</strong> — ¿qué IOCs específicos?</li></ul><p><strong>Plataformas relevantes:</strong></p><ul><li><strong>MISP</strong> — Malware Information Sharing Platform</li><li><strong>OpenCTI</strong> — plataforma open source de CTI</li><li><strong>TheHive + Cortex</strong> — case management + observable analysis</li></ul><p>📁 <a href="./07-threat-intelligence/"><code>./07-threat-intelligence/</code></a></p><hr><h2 id="💼-ramas-laborales-—-carrera-profesional-7-paths" tabindex="-1">💼 Ramas laborales — Carrera profesional (7 paths)</h2><blockquote><p>Roles de <strong>C-suite, GRC y privacy</strong> que evolucionan desde las áreas de conocimiento de arriba. Cada README tiene descripción, stack, certificaciones, roadmap, salarios Colombia y conexiones.</p></blockquote><table tabindex="0"><thead><tr><th>Rama</th><th>Tier salarial</th><th>Mid-USD/mes</th><th>Highlight</th></tr></thead><tbody><tr><td><a href="./ciso/"><code>ciso/</code></a></td><td><strong>S</strong></td><td>$7,500-14,000</td><td>Top jerárquico defensivo · vCISO como variante</td></tr><tr><td><a href="./iso-27001-lead-implementer/"><code>iso-27001-lead-implementer/</code></a></td><td>C/B</td><td>$1,500-3,000</td><td>Mayor demanda LATAM 2025-2026 (SaaS pre-sales US/EU)</td></tr><tr><td><a href="./data-protection-officer/"><code>data-protection-officer/</code></a></td><td>A</td><td>$2,000-4,000</td><td>CIPP + inglés legal = combo de oro</td></tr><tr><td><a href="./auditor-seguridad/"><code>auditor-seguridad/</code></a></td><td>C/B</td><td>$1,500-3,000</td><td>CISA = mejor ROI · Big 4 → industry +50-80%</td></tr><tr><td><a href="./risk-manager/"><code>risk-manager/</code></a></td><td>B/A</td><td>$1,800-3,500</td><td>CRISC + Open FAIR + Python = top 5%</td></tr><tr><td><a href="./business-continuity-manager/"><code>business-continuity-manager/</code></a></td><td>C/B</td><td>$1,500-3,000</td><td>DORA + NIS2 + CIRCIA empuja demanda</td></tr><tr><td><a href="./privacy-engineer/"><code>privacy-engineer/</code></a></td><td>A</td><td>$2,500-5,000</td><td>Combina dev + privacy + cripto · CIPT clave</td></tr></tbody></table><blockquote><p>Ver cada README para breakdown completo por nivel (Junior / Mid / Senior · Local / Remoto).</p></blockquote><hr><h2 id="🔄-relacion-con-la-seccion-ofensiva" tabindex="-1">🔄 Relación con la sección ofensiva</h2><blockquote><p>Cada técnica ofensiva en <code>01-CIBERSEGURIDAD/</code> debería tener su contramedida defensiva mapeada aquí.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ATT&amp;CK Technique  →  D3FEND Countermeasure  →  Wazuh/Sigma Detection Rule</span></span>
<span class="line"><span>   (TA0001)              (D3-***)                  (sigma/wazuh-rule.yml)</span></span></code></pre></div><p>Esto cierra el bucle <strong>Red ↔ Blue</strong> y es la filosofía de <strong>Purple Team</strong>.</p><hr><div align="center"><p><strong><a href="./../README">⬅ Volver al README principal</a></strong> · <strong><a href="./../03-AI-AGENTS-TOOLS/">🤖 Ir a AI Agents →</a></strong></p></div>`,83)])])}const h=e(d,[["render",i]]);export{u as __pageData,h as default};
